<script>
const procurementModeField=document.querySelector('[name="procurement_mode"]');
function syncConference(){document.getElementById('preProcurementConference').value=procurementModeField.value?(procurementModeField.value==='COMPETITIVE BIDDING'?'YES':'NO'):''}
procurementModeField.addEventListener('change',syncConference);syncConference();
const ppmpDialog=document.getElementById('ppmpDialog');ppmpDialog.addEventListener('close',()=>document.getElementById('toggleForm').focus());
const prPopup=document.getElementById('prPopup'),prFormFrame=document.getElementById('prFormFrame');document.getElementById('openPrForm').onclick=()=>{if(!prFormFrame.src)prFormFrame.src='purchase_requests.php?new=1&embed=1';prPopup.showModal()};document.getElementById('closePrForm').onclick=()=>prPopup.close();prPopup.addEventListener('click',event=>{if(event.target===prPopup)prPopup.close()});window.addEventListener('message',event=>{if(event.origin===location.origin&&event.data==='close-pr-popup')prPopup.close()});prFormFrame.addEventListener('load',()=>{try{if(prFormFrame.contentWindow.location.pathname.endsWith('/ppmp.php'))location.href='ppmp.php'}catch(error){}});
const form=document.getElementById('ppmpForm'),cartBody=document.getElementById('cart'),json=document.getElementById('itemsJson'),lines=[];function draw(){cartBody.innerHTML=lines.length?lines.map((x,i)=>`<tr><td>${x.code}</td><td>${x.description}</td><td>${x.unit}</td><td>${x.qty}</td><td>₱${Number(x.cost).toFixed(2)}</td><td>₱${(x.qty*x.cost).toFixed(2)}</td><td><button class="btn red ppmp-remove-item" type="button" onclick="lines.splice(${i},1);draw()" aria-label="Remove item" title="Remove item"><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M3 6h18M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2M5 6l1 14a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1L19 6M10 10v7M14 10v7"/></svg></button></td></tr>`).join(''):'<tr><td colspan="7" class="muted">No items selected.</td></tr>';json.value=JSON.stringify(lines);updateCartSummary()}document.getElementById('toggleForm').onclick=()=>ppmpDialog.showModal();document.getElementById('cancelForm').onclick=()=>ppmpDialog.close();document.getElementById('addItem').onclick=()=>{const s=document.getElementById('item'),o=s.selectedOptions[0],qty=+document.getElementById('qty').value,cost=+document.getElementById('cost').value;if(!s.value||qty<1||cost<0)return alert('Select an item and enter quantity and unit cost.');if(lines.some(x=>x.id===+s.value))return alert('This item is already included.');lines.push({id:+s.value,code:o.dataset.code,description:o.dataset.description,unit:o.dataset.unit,qty,cost});draw()};form.onsubmit=e=>{if((e.submitter?.value||'draft')==='submit'&&!lines.length){e.preventDefault();alert('Add at least one item.')}else if((e.submitter?.value||'draft')==='submit'&&lines.some(x=>x.request_id&&x.approval_status!=='APPROVED')){e.preventDefault();alert('Wait for Super Admin to approve all requested items before submitting.')}};
</script>
