l{min-width:210px;text-align:left!important}.ppmp-review-note{display:block;padding:8px 10px;border-left:3px solid #b7791f;background:#fff8e8;color:#60470f;font-size:12px;line-height:1.4;white-space:pre-wrap}.ppmp-review-empty{color:#93a1aa}.ppmp-request-dialog{width:min(700px,94vw);padding:0;border:0;border-radius:8px;box-shadow:0 25px 80px #102b3b66}.ppmp-request-dialog::backdrop{background:#142a397d}.ppmp-request-dialog header,.ppmp-request-dialog footer{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:14px 17px;background:#f0f7fa;border-bottom:1px solid #d8e5ec}.ppmp-request-dialog header strong,.ppmp-request-dialog header small{display:block}.ppmp-request-dialog header small{margin-top:3px;color:#647b8a}.ppmp-request-dialog footer{justify-content:flex-end;border-top:1px solid #d8e5ec;border-bottom:0;background:#fff}.ppmp-request-body{padding:18px}.ppmp-request-message{min-height:18px;margin:12px 0 0;color:#b42318;font-weight:700}.ppmp-request-toast{position:fixed;top:18px;right:18px;z-index:1000;max-width:390px;padding:12px 16px;border-left:4px solid #087f5b;border-radius:6px;background:#e1f4ec;color:#086a4c;box-shadow:0 10px 30px #102b3b2b;font-weight:700}@media(max-width:1100px){.ppmp-catalog{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.ppmp-catalog{grid-template-columns:1fr}.ppmp-item-dialog{width:100vw;max-height:100vh;border-radius:0}}</style>
<style>.ppmp-request-status{display:block;width:max-content;margin-top:5px;padding:3px 7px;border-radius:999px;background:#fff0cc;color:#8b5d00;font-size:10px;font-weight:900}.ppmp-request-status.rejected{background:#ffe2e2;color:#a92121}.ppmp-request-pending{background:#fffdf7}.ppmp-request-rejected{background:#fffafa}.ppmp-form-footer button:disabled{cursor:not-allowed;opacity:.5}</style>
<script>
const originalPicker=document.querySelector('.line-picker');
const catalogSection=document.createElement('dialog');catalogSection.className='ppmp-item-dialog';catalogSection.innerHTML='<header class="ppmp-dialog-head"><div><strong>Select PPMP Items</strong><small>Search, filter, and add items to the PPMP cart.</small></div><button class="btn light" type="button" data-close-catalog>Back</button></header><div class="ppmp-dialog-body"><div class="ppmp-catalog-tools"><input class="search" id="catalogSearch" placeholder="Search item code or name"><select class="search" id="categoryFilter" aria-label="Item category"><option value="all">All Categories</option><option value="MEDICAL SUPPLIES">Medical Supply</option><option value="MEDICAL INSTRUMENTS">Medical Instrument</option></select><select class="search" id="stockFilter" aria-label="Stock status"><option value="all">All Items</option><option value="low">Low Stock</option><option value="out">Out of Stock</option><option value="normal">Normal Stock</option></select><label class="ppmp-select-all">Select All <input type="checkbox" id="selectVisible" aria-describedby="selectStockHint"></label><span class="muted" id="selectStockHint">Select All applies to all items matching the current filters and search.</span></div><div class="ppmp-catalog" id="ppmpCatalog"><span class="muted">Loading items...</span></div></div><footer class="ppmp-dialog-foot"><button class="btn light" type="button" id="requestNewItem">Request New Item</button><button class="btn light" type="button" data-close-catalog>Cancel</button><button class="btn green" type="button" id="addSelected">Add Selected to PPMP</button></footer>';document.body.append(catalogSection);originalPicker.hidden=true;
const selectedCatalogCount=document.createElement('span');selectedCatalogCount.className='ppmp-selected-count';selectedCatalogCount.setAttribute('role','status');selectedCatalogCount.setAttribute('aria-live','polite');selectedCatalogCount.textContent='0 items selected';catalogSection.querySelector('#addSelected').before(selectedCatalogCount);
const cartTable=cartBody.closest('table');cartTable.classList.add('ppmp-cart-table');cartBody.querySelector('[colspan]')?.setAttribute('colspan','9');cartTable.querySelector('thead tr').innerHTML='<th><input type="checkbox" id="selectCartAll"></th><th>Code</th><th>Item Name</th><th>Unit</th><th>Quantity</th><th>Unit Cost</th><th>Total</th><th class="ppmp-review-column">Reviewer Comment</th><th></th>';const cartTools=document.createElement('div');cartTools.className='ppmp-cart-tools';cartTools.innerHTML='<strong>PPMP Cart</strong><button class="btn green" type="button" id="openCatalog">Add Items</button><button class="btn red" type="button" id="removeSelectedCart">Remove Selected</button><button class="btn light" type="button" id="clearCart">Clear Cart</button>';cartTable.parentElement.before(cartTools);
let catalogItems=[],ppmpReviewComments=new Map();window.setPpmpReviewComments=comments=>{ppmpReviewComments=new Map();(comments||[]).forEach(comment=>{const itemId=Number(comment.item_id),itemComments=ppmpReviewComments.get(itemId)||[];itemComments.push(comment);ppmpReviewComments.set(itemId,itemComments)});lines.sort((a,b)=>Number(ppmpReviewComments.has(Number(b.id)))-Number(ppmpReviewComments.has(Number(a.id))));draw()};
function syncPendingItemState(){const pending=lines.some(item=>item.request_id&&item.approval_status!=='APPROVED'),submit=form.querySelector('[name="save_intent"][value="submit"]');if(submit){submit.disabled=pending;submit.title=pending?'All requested items must be approved before submission.':''}return pending}
function updateCartSummary(){const total=lines.reduce((sum,item)=>{const amount=Number(item.qty)*Number(item.cost);return sum+(Number.isFinite(amount)?amount:0)},0),budget=Number(form.elements.reference_budget.value||0),remaining=budget-total,format=value=>value.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});document.getElementById('ppmpTotalItems').textContent=String(lines.length);document.getElementById('ppmpReferenceBudget').textContent=format(budget);document.getElementById('ppmpTotalCost').textContent=format(total);const remainingElement=document.getElementById('ppmpRemainingBudget');remainingElement.textContent=format(remaining);remainingElement.classList.toggle('over-budget',remaining<0)}form.elements.reference_budget.addEventListener('input',updateCartSummary);form.addEventListener('submit',event=>{if((event.submitter?.value||'draft')!=='submit')return;if(!form.checkValidity()){event.preventDefault();event.stopImmediatePropagation();form.reportValidity();const invalid=form.querySelector(':invalid');invalid?.scrollIntoView({behavior:'smooth',block:'center'});invalid?.focus();return}if(!lines.length){event.preventDefault();event.stopImmediatePropagation();alert('Add at least one item before submitting the PPMP.');return}const invalidItem=lines.find(item=>Number(item.qty)<1||Number(item.cost)<0);if(invalidItem){event.preventDefault();event.stopImmediatePropagation();alert('Every item must have a valid quantity and unit cost.');return}const total=lines.reduce((sum,item)=>sum+(Number(item.qty)*Number(item.cost)),0),budget=Number(form.elements.reference_budget.value);if(total>budget){event.preventDefault();event.stopImmediatePropagation();alert(`The item total exceeds the reference budget by ₱${(total-budget).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}.`)}},true);
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function suggestedQty(item){const minimum=Number(item.minimum_stock||0),stock=Number(item.current_stock||0);return stock<=minimum?Math.max(1,minimum*2):1;}
function addCatalogItem(item,automatic=false){if(lines.some(x=>x.id===Number(item.id)))return;lines.push({id:Number(item.id),code:item.item_code,description:catalogItemName(item),unit:item.unit||'',qty:suggestedQty(item),cost:Number(item.unit_cost||0),remarks:automatic?'Automatically added: '+(Number(item.current_stock)<=0?'Out of stock':'Low stock'):''});draw();}
draw=function(){cartBody.innerHTML=lines.length?lines.map((x,i)=>{const reviews=ppmpReviewComments.get(Number(x.id))||[],requestStatus=x.request_id?(x.approval_status||'PENDING'):'';return `<tr data-cart-index="${i}" class="${requestStatus==='REJECTED'?'ppmp-request-rejected':(requestStatus&&requestStatus!=='APPROVED'?'ppmp-request-pending':'')}"><td><input type="checkbox" data-cart-select></td><td>${esc(x.code)}</td><td>${esc(x.description)}${requestStatus&&requestStatus!=='APPROVED'?`<span class="ppmp-request-status ${requestStatus.toLowerCase()}">${requestStatus==='REJECTED'?'ITEM REQUEST REJECTED':'PENDING ITEM APPROVAL'}</span>`:''}</td><td>${esc(x.unit)}</td><td><input class="cart-input" data-field="qty" type="number" min="1" value="${x.qty}"></td><td><input class="cart-input" data-field="cost" type="number" min="0" step="0.01" value="${Number(x.cost).toFixed(2)}"></td><td data-line-total>₱${(x.qty*x.cost).toFixed(2)}</td><td class="ppmp-review-cell">${reviews.length?reviews.map(review=>`<span class="ppmp-review-note">${esc(review.review_field)}: ${esc(review.comment)} - ${esc(review.resolution_status)}${(review.follow_ups||[]).map((followUp,index)=>`\nFOLLOW-UP ${index+1}: ${esc(followUp.comment)}`).join('')}</span>`).join(''):'<span class="ppmp-review-empty">—</span>'}</td><td><button class="btn red ppmp-remove-item" type="button" data-remove-one="${i}" aria-label="Remove ${esc(x.description)}" title="Remove item"><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M3 6h18M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2M5 6l1 14a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1L19 6M10 10v7M14 10v7"/></svg></button></td></tr>`}).join(''):'<tr><td colspan="9" class="muted">No items selected.</td></tr>';json.value=JSON.stringify(lines);updateCartSummary();syncPendingItemState();cartBody.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>{const row=input.closest('tr'),item=lines[Number(row.dataset.cartIndex)],field=input.dataset.field;item[field]=field==='qty'||field==='cost'?Number(input.value):input.value;row.querySelector('[data-line-total]').textContent='₱'+(item.qty*item.cost).toFixed(2);json.value=JSON.stringify(lines);updateCartSummary()});cartBody.querySelectorAll('[data-remove-one]').forEach(b=>b.onclick=()=>{lines.splice(Number(b.dataset.removeOne),1);draw()})};
function itemState(i){const stock=Number(i.current_stock),minimum=Number(i.minimum_stock);return stock<=0?'out':(stock<=minimum?'low':'normal')}
function catalogItemName(item){return String(item.item_description??'').trim()||item.item_name||'Unnamed item'}
function visibleCatalog(){const q=document.getElementById('catalogSearch').value.toLowerCase(),filter=document.getElementById('stockFilter').value,category=document.getElementById('categoryFilter').value,priority={out:0,low:1,normal:2};return catalogItems.filter(i=>(i.item_code+' '+catalogItemName(i)).toLowerCase().includes(q)&&(filter==='all'||itemState(i)===filter)&&(category==='all'||String(i.category??'').trim().toUpperCase()===category)).sort((a,b)=>priority[itemState(a)]-priority[itemState(b)])}
function syncCatalogSelection(){const boxes=[...catalogSection.querySelectorAll('[data-catalog-select]')],selected=boxes.filter(c=>c.checked).length,all=document.getElementById('selectVisible');all.checked=boxes.length>0&&selected===boxes.length;all.indeterminate=selected>0&&selected<boxes.length;all.disabled=boxes.length===0;selectedCatalogCount.textContent=`${selected} item${selected===1?'':'s'} selected`}
function drawCatalog(){const box=document.getElementById('ppmpCatalog');box.innerHTML=visibleCatalog().map(i=>{const stock=Number(i.current_stock),minimum=Number(i.minimum_stock),state=itemState(i),label=state==='out'?'OUT OF STOCK':(state==='low'?'LOW STOCK':'STOCK: '+stock);return `<article class="ppmp-item ${state}" data-catalog-item="${i.id}"><input type="checkbox" data-catalog-select value="${i.id}"><div><strong>${esc(catalogItemName(i))}</strong><small>${esc(i.unit||'')} · Minimum ${minimum} · Suggested ${suggestedQty(i)}</small><b class="ppmp-stock">${label}</b></div><button class="btn ${state!=='normal'?'gold':'light'}" type="button" data-add-catalog="${i.id}">Add</button></article>`}).join('')||'<span class="muted">No matching items.</span>';box.querySelectorAll('[data-catalog-select]').forEach(c=>c.onchange=syncCatalogSelection);syncCatalogSelection();box.querySelectorAll('[data-add-catalog]').forEach(b=>b.onclick=()=>addCatalogItem(catalogItems.find(i=>Number(i.id)===Number(b.dataset.addCatalog))))}
async function loadPpmpCatalog(){catalogItems=await fetch('?catalog=1').then(r=>r.json());drawCatalog()}
async function openCatalog(){if(!catalogItems.length)await loadPpmpCatalog();catalogSection.showModal()}
document.getElementById('openCatalog').onclick=openCatalog;catalogSection.querySelectorAll('[data-close-catalog]').forEach(b=>b.onclick=()=>catalogSection.close());catalogSection.addEventListener('click',e=>{if(e.target===catalogSection)catalogSection.close()});document.getElementById('catalogSearch').oninput=drawCatalog;document.getElementById('stockFilter').onchange=drawCatalog;document.getElementById('categoryFilter').onchange=drawCatalog;document.getElementById('selectVisible').onchange=function(){catalogSection.querySelectorAll('[data-catalog-select]').forEach(c=>c.checked=this.checked);syncCatalogSelection()};document.getElementById('addSelected').onclick=()=>{const selected=[...catalogSection.querySelectorAll('[data-catalog-select]:checked')];selected.forEach(c=>addCatalogItem(catalogItems.find(i=>Number(i.id)===Number(c.value))));selected.forEach(c=>c.checked=false);syncCatalogSelection();catalogSection.close()};document.getElementById('selectCartAll').onchange=function(){cartBody.querySelectorAll('[data-cart-select]').forEach(c=>c.checked=this.checked)};document.getElementById('removeSelectedCart').onclick=()=>{const indexes=[...cartBody.querySelectorAll('[data-cart-select]:checked')].map(c=>Number(c.closest('tr').dataset.cartIndex)).sort((a,b)=>b-a);indexes.forEach(i=>lines.splice(i,1));draw()};document.getElementById('clearCart').onclick=()=>{if(confirm('Remove all items from the PPMP cart?')){lines.splice(0);draw()}};
const itemRequestDialog=document.getElementById('itemRequestDialog'),itemRequestForm=document.getElementById('itemRequestForm'),itemRequestMessage=document.getElementById('itemRequestMessage'),itemRequestToast=document.getElementById('itemRequestToast');ppmpDialog.appendChild(itemRequestToast);let itemRequestReturnToCatalog=false;document.getElementById('requestNewItem').onclick=()=>{itemRequestReturnToCatalog=true;catalogSection.close();itemRequestMessage.textContent='';itemRequestDialog.showModal()};itemRequestDialog.querySelectorAll('[data-close-item-request]').forEach(button=>button.onclick=()=>itemRequestDialog.close());itemRequestDialog.addEventListener('close',()=>{if(itemRequestReturnToCatalog){itemRequestReturnToCatalog=false;catalogSection.showModal()}});itemRequestDialog.addEventListener('click',event=>{if(event.target===itemRequestDialog)itemRequestDialog.close()});itemRequestForm.addEventListener('submit',async event=>{event.preventDefault();if(!itemRequestForm.reportValidity())return;const submit=itemRequestForm.querySelector('[type="submit"]');submit.disabled=true;itemRequestMessage.textContent='';try{const response=await fetch(location.href,{method:'POST',body:new FormData(itemRequestForm)}),result=await response.json();if(!response.ok||!result.ok)throw new Error(result.message||'Unable to submit the item request.');if(result.item)lines.push(result.item);draw();itemRequestReturnToCatalog=false;itemRequestDialog.close();itemRequestForm.reset();itemRequestForm.elements.requested_quantity.value='1';itemRequestForm.elements.estimated_unit_cost.value='0.00';itemRequestToast.textContent=result.message;itemRequestToast.hidden=false;clearTimeout(window.ppmpItemRequestToastTimer);window.ppmpItemRequestToastTimer=setTimeout(()=>itemRequestToast.hidden=true,5000)}catch(error){itemRequestMessage.textContent=error.message}finally{submit.disabled=false}});new MutationObserver(syncPendingItemState).observe(form.querySelector('.ppmp-form-footer .actions'),{childList:true,subtree:true});window.addEventListener('load',syncPendingItemState);
</script>
